assertions.text:
  assert.deepEqual(detect(`function f(id) {
  const dir = assignmentDir(fgosDir, id);
  return fsp.readdir(dir);
}`), ['probe.mjs: f: readdir(dir)']);

  assert.deepEqual(detect(`function f(root) {
  const base = path.join(
    root,
    '.fgos',
    'assignments',
  );
  return fs.readdirSync(base);
}`), ['probe.mjs: f: readdirSync(base)']);

  assert.deepEqual(detect(`function f(root) {
  const base =
    path.join(root, 'assignments');
  return fs.readdirSync(base);
}`), ['probe.mjs: f: readdirSync(base)']);

  assert.deepEqual(detect(`import { readdirSync as ls } from 'node:fs';
function f(fgosDir) {
  return ls(path.join(fgosDir, 'assignments'));
}`), ["probe.mjs: f: ls(path.join(fgosDir, 'assignments'))"]);

  assert.deepEqual(detect(`function walk(dir) {
  for (const e of fs.readdirSync(dir)) walk(path.join(dir, e));
}
walk(fgosDir);`), ['probe.mjs: walk: readdirSync(dir)']);

  assert.deepEqual(detect(`const base = path.join(fgosDir, 'assignments');
/*
 * fs.readdirSync(base);
 */
const url = 'http://x//y'; fs.readdirSync(base);`), ['probe.mjs: <module>: readdirSync(base)']);

  assert.deepEqual(statics("import {
  a,
  b,
} from './g.mjs';
export { h } from './h.mjs';
import def, { i } from './i.mjs';"), ['./g.mjs', './h.mjs', './i.mjs']);

  assert.deepEqual(statics("// import './x.mjs'
/* import './y.mjs' */
const s = "import './z.mjs'";
const t = `from './w.mjs'`;
export const v = 1;
export { v as u };"), []);

  assert.deepEqual(caught('const alive = process.kill(pid, 0) && process.kill.call(process, other.pid, 0);
// process.kill(pid, 9) is never sent
/* spawn(x) */
const killSwitch = 1;'), []);

  write(root, 'ok.test.mjs', "import { test } from 'node:test';
import assert from 'node:assert/strict';
test('ok', () => assert.ok(true));
");
